+import { LINEAR_UNITS, TEMPERATURE_UNITS } from "./units.ts";
+
+type UnitKind = "length" | "mass" | "temperature";
+
+const ABSOLUTE_ZERO: Record<(typeof TEMPERATURE_UNITS)[number], number> = {
+  C: -273.15,
+  F: -459.67,
+  K: 0,
+};
+
+function kindOf(unit: string): UnitKind {
+  if ((TEMPERATURE_UNITS as readonly string[]).includes(unit)) {
+    return "temperature";
+  }
+  if (Object.hasOwn(LINEAR_UNITS, unit)) {
+    return LINEAR_UNITS[unit].kind;
+  }
+  throw new Error(`unknown unit: ${unit}`);
+}
+
+function toCelsius(value: number, unit: string): number {
+  switch (unit) {
+    case "C":
+      return value;
+    case "F":
+      return ((value - 32) * 5) / 9;
+    default:
+      return value - 273.15;
+  }
+}
+
+function fromCelsius(celsius: number, unit: string): number {
+  switch (unit) {
+    case "C":
+      return celsius;
+    case "F":
+      return (celsius * 9) / 5 + 32;
+    default:
+      return celsius + 273.15;
+  }
+}
+
+function convertTemperature(value: number, from: string, to: string): number {
+  if (value < ABSOLUTE_ZERO[from as keyof typeof ABSOLUTE_ZERO]) {
+    throw new RangeError(`${value} ${from} is below absolute zero`);
+  }
+  if (from === to) {
+    return value;
+  }
+  return fromCelsius(toCelsius(value, from), to);
+}
+
